package com.campus.quiz.controller;

import com.campus.quiz.model.*;import com.campus.quiz.repo.*;import com.campus.quiz.service.QuizService;import com.campus.quiz.web.QuizForm;
import org.springframework.security.core.Authentication;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;import org.springframework.web.servlet.mvc.support.RedirectAttributes;

@Controller @RequestMapping("/teacher")
public class TeacherController {
 private final QuizService service;private final UserAccountRepository users;private final PasswordEncoder passwordEncoder;
 public TeacherController(QuizService service,UserAccountRepository users,PasswordEncoder passwordEncoder){this.service=service;this.users=users;this.passwordEncoder=passwordEncoder;}
 @GetMapping public String dashboard(Authentication auth,Model model){UserAccount teacher=current(auth);var quizzes=service.quizzesFor(teacher.getSubject());java.util.Map<Long,Boolean> editable=new java.util.HashMap<>();for(Quiz q:quizzes)editable.put(q.getId(),service.canEdit(q.getId()));model.addAttribute("teacher",teacher);model.addAttribute("quizzes",quizzes);model.addAttribute("editable",editable);model.addAttribute("now",java.time.LocalDateTime.now());model.addAttribute("students",users.findByRoleOrderByDisplayNameAsc("STUDENT"));return "teacher/dashboard";}
 @GetMapping("/quizzes/new") public String newQuiz(Authentication auth,Model model){model.addAttribute("teacher",current(auth));model.addAttribute("form",new QuizForm());return "teacher/quiz-form";}
 @PostMapping("/quizzes") public String create(@ModelAttribute("form") QuizForm form,Authentication auth,Model model,RedirectAttributes ra){try{service.create(form,current(auth));ra.addFlashAttribute("success","Quiz created and scheduled.");return "redirect:/teacher";}catch(Exception e){model.addAttribute("teacher",current(auth));model.addAttribute("error",e.getMessage());return "teacher/quiz-form";}}
 @GetMapping("/quizzes/{id}/edit") public String edit(@PathVariable Long id,Authentication auth,Model model,RedirectAttributes ra){Quiz quiz=service.owned(id,current(auth));if(!service.canEdit(id)){ra.addFlashAttribute("error","This quiz already has student attempts, so its questions are locked. Create a new quiz for updated questions.");return "redirect:/teacher/quizzes/"+id+"/results";}model.addAttribute("teacher",current(auth));model.addAttribute("quiz",quiz);model.addAttribute("form",service.toForm(quiz));return "teacher/quiz-form";}
 @PostMapping("/quizzes/{id}") public String update(@PathVariable Long id,@ModelAttribute("form") QuizForm form,Authentication auth,Model model,RedirectAttributes ra){try{service.update(id,form,current(auth));ra.addFlashAttribute("success","Quiz changes saved.");return "redirect:/teacher";}catch(Exception e){model.addAttribute("teacher",current(auth));model.addAttribute("error",e.getMessage());model.addAttribute("quiz",service.owned(id,current(auth)));return "teacher/quiz-form";}}
 @GetMapping("/quizzes/{id}/results") public String results(@PathVariable Long id,Authentication auth,Model model){Quiz quiz=service.owned(id,current(auth));model.addAttribute("teacher",current(auth));model.addAttribute("quiz",quiz);model.addAttribute("attempts",service.attemptsFor(id,current(auth)));model.addAttribute("canEdit",service.canEdit(id));return "teacher/results";}
 @GetMapping("/password") public String passwordPage(Authentication auth,Model model){model.addAttribute("teacher",current(auth));return "teacher/password";}
 @PostMapping("/password") public String changePassword(Authentication auth,@RequestParam String currentPassword,@RequestParam String newPassword,@RequestParam String confirmPassword,Model model,RedirectAttributes ra){UserAccount teacher=current(auth);if(!passwordEncoder.matches(currentPassword,teacher.getPassword())){model.addAttribute("teacher",teacher);model.addAttribute("error","Current password is incorrect.");return "teacher/password";}if(newPassword.length()<8){model.addAttribute("teacher",teacher);model.addAttribute("error","New password must be at least 8 characters.");return "teacher/password";}if(!newPassword.equals(confirmPassword)){model.addAttribute("teacher",teacher);model.addAttribute("error","New password and confirmation do not match.");return "teacher/password";}if(passwordEncoder.matches(newPassword,teacher.getPassword())){model.addAttribute("teacher",teacher);model.addAttribute("error","Choose a password different from your current password.");return "teacher/password";}teacher.setPassword(passwordEncoder.encode(newPassword));users.save(teacher);ra.addFlashAttribute("success","Password changed successfully.");return "redirect:/teacher/password";}
 private UserAccount current(Authentication auth){return users.findByUsername(auth.getName()).orElseThrow();}
}
